#include <sstream>
#include <string>
#include <unordered_set>
#include <vector>

std::string firstRepeated(const std::vector<std::string>& words) {
    std::unordered_set<std::string> seen;
    for (const std::string& word : words) {
        if (seen.count(word) > 0) {
            return word;
        }
        seen.insert(word);
    }
    return "";
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream stream(line);
    std::vector<std::string> words;
    std::string w;
    while (stream >> w) {
        words.push_back(w);
    }
    std::string word = firstRepeated(words);
    std::cout << (word.empty() ? "none" : word) << "\n";
    return 0;
}

