package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func firstRepeated(words []string) string {
	seen := make(map[string]bool)
	for _, word := range words {
		if seen[word] {
			return word
		}
		seen[word] = true
	}
	return ""
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	words := strings.Fields(scanner.Text())
	word := firstRepeated(words)
	if word == "" {
		word = "none"
	}
	fmt.Println(word)
}
